<script setup lang="ts">
import { assistantStatus, getAssistantStatus, refreshAssistantStatus } from '../composables/useAssistantStatus'
import { computed } from 'vue'
import { RefreshCw, Database } from 'lucide-vue-next'
const state = computed(() => getAssistantStatus('portfolio'))
const narrow = computed(() => assistantStatus.value?.coverage?.narrow)
const broad = computed(() => assistantStatus.value?.coverage?.broad)
const labels: Record<string, string> = { complete: '已采集', partial: '部分可用', failed: '失败', timed_out: '超时', not_collected: '未采集' }
const at = (value?: string) => value ? /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) : '--'
</script>
<template>
  <section class="mb-5 border-b border-border pb-4" aria-label="持仓资料状态">
    <header class="flex flex-wrap items-center justify-between gap-3"><h2 class="inline-flex items-center gap-2 text-sm font-semibold"><Database :size="16" />账户与资料状态</h2><button type="button" class="inline-flex min-h-9 items-center gap-2 rounded border border-border px-3 text-xs hover:bg-secondary" @click="refreshAssistantStatus"><RefreshCw :size="14" />检查状态</button></header>
    <p class="mt-2 text-xs text-muted-foreground">账户记录 {{ at(assistantStatus?.account_snapshot_at) }} · 日K目标 {{ assistantStatus?.target_date || '--' }}</p>
    <div v-if="narrow" class="mt-4 grid gap-6 border-y border-border py-4 md:grid-cols-2">
      <section class="min-w-0"><h3 class="text-sm font-semibold">狭义广度 · 重点资料覆盖</h3><p :class="['mt-2 text-sm', narrow.healthy ? 'text-emerald-300' : 'text-amber-200']">{{ narrow.healthy ? '数据健康' : '重点资料待补' }} · 标的 {{ narrow.covered_count }}/{{ narrow.tracked_count }}</p><p class="mt-2 text-xs text-muted-foreground">持仓与重点关注标的，以及境内大盘、纳指、美元、黄金和有色参考。</p><details class="mt-3"><summary class="cursor-pointer text-xs text-sky-300">查看逐项时效与缺口</summary><div class="mt-3 divide-y divide-border"><div v-for="item in narrow.items" :key="item.symbol" class="flex flex-wrap justify-between gap-2 py-2 text-xs"><span>{{ item.name }} · {{ item.symbol }}</span><span :class="item.fresh || item.exempt ? 'text-muted-foreground' : 'text-amber-200'">{{ item.exempt ? '未上市，不计入缺失' : at(item.observed_at) }} · {{ item.exempt ? '' : item.fresh ? '有效' : '待补' }}</span></div><div v-for="item in narrow.references" :key="item.symbol" class="py-2 text-xs"><p class="flex flex-wrap justify-between gap-2"><span>{{ item.name }}</span><span :class="item.fresh ? 'text-muted-foreground' : 'text-amber-200'">{{ at(item.observed_at) }} · {{ item.fresh ? '时效有效' : '待补' }}</span></p><p v-if="item.reason" class="mt-1 text-amber-200">{{ item.reason }}</p></div></div><p v-if="narrow.missing_groups.length" class="mt-2 text-xs text-amber-200">缺少有效参考组：{{ narrow.missing_groups.join('、') }}</p><p class="mt-3 text-xs leading-6 text-muted-foreground">{{ narrow.boundary }}</p></details></section>
      <section class="min-w-0"><h3 class="text-sm font-semibold">广义广度 · 全市场覆盖</h3><p class="mt-2 text-sm">{{ broad?.covered_count || 0 }}/{{ broad?.universe_count || 0 }} · {{ broad?.coverage_pct || 0 }}%</p><p class="mt-2 text-xs text-muted-foreground">统计日期 {{ broad?.as_of || '--' }} · 仅描述全市场统计的完整程度，不影响狭义健康灯。</p><p v-if="assistantStatus?.backfill?.total_symbols" class="mt-3 text-xs text-muted-foreground">全市场日K续传已核验 {{ assistantStatus.backfill.completed_count }}/{{ assistantStatus.backfill.total_symbols }}，剩余 {{ assistantStatus.backfill.remaining_count }}；每轮最多200只，后台分批继续。</p><p class="mt-3 text-xs text-muted-foreground">最近启动采集 {{ at(assistantStatus?.startup?.launched_at) }}</p></section>
    </div>
    <details class="mt-3"><summary class="cursor-pointer text-sm text-sky-300">{{ state.text }} · 来源与缺口</summary><div class="mt-3 grid gap-x-8 md:grid-cols-2"><article v-for="source in assistantStatus?.sources || []" :key="source.source" class="border-b border-border py-3 text-xs"><p class="font-medium">{{ source.name }} · {{ labels[source.status] || source.status }}{{ source.fresh ? '' : ' · 待更新' }}</p><p class="mt-1 text-muted-foreground">采集 {{ at(source.finished_at) }} · 目标日期 {{ source.target_date || '--' }}</p><p v-if="source.boundary" class="mt-1 text-muted-foreground">{{ source.boundary }}</p><p v-for="(gap, index) in source.failures" :key="index" class="mt-1 text-amber-200">{{ gap.symbol || gap.source }}：{{ gap.reason }}</p><p v-for="item in source.coverage" :key="item.symbol" class="mt-1 text-muted-foreground">{{ item.symbol }} · {{ item.annual_report_found ? '已取得年报正文' : '年报正文尚未取得' }}</p></article></div><p class="mt-3 text-xs text-muted-foreground">{{ assistantStatus?.boundary }}</p></details>
  </section>
</template>
